(function(){
'use strict';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let rollCallSaving=false, planHydrating=false, rpeHydrating=false;
const c=()=>window.VolleySupabase?.getClient?.()||null;
const st=()=>typeof appState!=='undefined'?appState:null;
const me=()=>{try{return typeof getCurrentUser==='function'?getCurrentUser():null}catch(_){return null}};
const same=(a,b)=>String(a??'')===String(b??'');

function injectCss(){if(document.getElementById('hotfix-20260809c-css'))return;const s=document.createElement('style');s.id='hotfix-20260809c-css';s.textContent=`
.session-detail-hero .session-delete-btn{display:none!important}
.event-delete-training-btn{border-color:#fecaca!important;color:#b91c1c!important;margin-right:auto}
.training-rpe-panel.is-answered .training-rpe-slider-wrap{display:none!important}
.training-rpe-answered{display:flex;gap:.6rem;align-items:center;padding:.8rem 1rem;margin-top:.75rem;border:1px solid #bbf7d0;background:#f0fdf4;color:#166534;border-radius:10px;font-weight:700}
.event-duration-group{min-width:180px}
`;document.head.appendChild(s)}

function localPlayerByAny(id){const v=String(id??'');return(st()?.players||[]).find(p=>[p.id,p.supabaseId,p.legacy_id,p.legacyId,p.profile_id,p.authId].filter(Boolean).map(String).includes(v))||null}
function localEventByAny(id){const v=String(id??'');return(st()?.events||[]).find(e=>[e.id,e.legacy_id,e.legacyId].filter(Boolean).map(String).includes(v))||null}
async function eventUuid(id){if(UUID.test(String(id||'')))return String(id);const db=c();if(!db)return null;const {data}=await db.from('events').select('id').eq('legacy_id',String(id)).maybeSingle();return data?.id||null}

async function syncPlayerMappings(){const db=c(),state=st();if(!db||!state)return;const {data,error}=await db.from('players').select('id,legacy_id,profile_id,profiles:profile_id(username)');if(error)return;for(const row of data||[]){const username=String(row.profiles?.username||'').toLowerCase();let p=(state.players||[]).find(x=>String(x.supabaseId||'')===String(row.id)||String(x.legacy_id||x.legacyId||'')===String(row.legacy_id||'')||(username&&String(x.username||'').toLowerCase()===username));if(p){p.supabaseId=row.id;p.profile_id=p.profile_id||row.profile_id;if(row.legacy_id&&!p.legacy_id)p.legacy_id=row.legacy_id;}}
}
async function playerUuid(localId){const p=localPlayerByAny(localId);if(p?.supabaseId&&UUID.test(String(p.supabaseId)))return p.supabaseId;if(UUID.test(String(localId||'')))return String(localId);const db=c();if(!db)return null;if(p?.username){const {data:prof}=await db.from('profiles').select('id').ilike('username',p.username).maybeSingle();if(prof?.id){const {data:row}=await db.from('players').select('id').eq('profile_id',prof.id).maybeSingle();if(row?.id){p.supabaseId=row.id;return row.id;}}}const {data:legacy}=await db.from('players').select('id').eq('legacy_id',String(localId)).maybeSingle();if(legacy?.id){if(p)p.supabaseId=legacy.id;return legacy.id;}const u=me();if(u?.playerId&&same(u.playerId,localId)){const ident=await window.VolleySupabase?.getIdentity?.();if(ident?.data?.player?.id){if(p)p.supabaseId=ident.data.player.id;return ident.data.player.id;}}return null}
async function ensurePlayerUuid(localPlayer){let id=await playerUuid(localPlayer.id);if(id)return id;const db=c();if(!db)return null;const clubId=me()?.clubId||window.VolleySupabase?.config?.clubId;if(!clubId)return null;const payload={legacy_id:String(localPlayer.id),club_id:clubId,dorsal:Number.isFinite(Number(localPlayer.number))?Number(localPlayer.number):null,position:localPlayer.position||null,active:true};const {data,error}=await db.from('players').insert(payload).select('id').single();if(error){console.warn('[Hotfix] No se pudo crear fila de jugadora',localPlayer.id,error);return null}localPlayer.supabaseId=data.id;return data.id}

function dedupeAttendanceState(){const state=st();if(!state)return;const seen=new Map();for(const row of state.trainingConfirmations||[]){const ev=String(row.eventId||row.eventIdLegacy||''),p=localPlayerByAny(row.playerId||row.playerIdLegacy),pid=String(p?.supabaseId||p?.id||row.playerId||row.playerIdLegacy||'');seen.set(ev+'|'+pid,{...row,playerId:p?.id||row.playerId});}state.trainingConfirmations=[...seen.values()];}
async function hydrateOwnAttendance(){const db=c(),state=st(),u=me();if(!db||!state||!u?.playerId)return;await syncPlayerMappings();const pid=await playerUuid(u.playerId);if(!pid)return;const {data,error}=await db.from('attendance').select('id,event_id,player_response,updated_at,created_at').eq('player_id',pid);if(error)return;state.trainingConfirmations=(state.trainingConfirmations||[]).filter(x=>!same(localPlayerByAny(x.playerId||x.playerIdLegacy)?.id||x.playerId,u.playerId));for(const r of data||[]){if(!r.player_response)continue;const ev=localEventByAny(r.event_id);state.trainingConfirmations.push({eventId:ev?.id||r.event_id,playerId:u.playerId,status:r.player_response,timestamp:r.updated_at||r.created_at});}dedupeAttendanceState();try{saveAppData(state)}catch(_){} }

function patchAttendance(){const baseLoad=window.loadAttendanceFromSupabase;if(typeof baseLoad==='function'&&!baseLoad.__hotfixC){const wrapped=async function(opts={}){const modal=document.getElementById('modal-verify-attendance');const wasActive=modal?.classList.contains('active');if(rollCallSaving&&wasActive)modal.classList.remove('active');const res=await baseLoad.call(this,opts);await syncPlayerMappings();dedupeAttendanceState();if(rollCallSaving&&wasActive)modal.classList.add('active');return res};wrapped.__hotfixC=true;window.loadAttendanceFromSupabase=wrapped}
const baseConfirm=window.confirmTrainingAttendance;if(typeof baseConfirm==='function'&&!baseConfirm.__hotfixC){const wrapped=async function(eventId,status,btn){const r=await baseConfirm.call(this,eventId,status,btn);await hydrateOwnAttendance();try{renderHomePortalRSVP();renderTraining();renderHomeDashboard();if(typeof activeSessionId!=='undefined'&&same(activeSessionId,eventId))renderSessionCenterDetail()}catch(_){}return r};wrapped.__hotfixC=true;window.confirmTrainingAttendance=wrapped}
}

async function saveRollCallCapture(e){if(e.target?.id!=='form-verify-attendance'||rollCallSaving)return;e.preventDefault();e.stopImmediatePropagation();rollCallSaving=true;const form=e.target,btn=form.querySelector('button[type="submit"]'),eventId=document.getElementById('verify-attendance-event-id')?.value;const db=c();if(!db||!eventId){rollCallSaving=false;return}if(btn){btn.disabled=true;btn.textContent='Guardando…'}try{await syncPlayerMappings();const evId=await eventUuid(eventId);if(!evId)throw new Error('No se encuentra el entrenamiento en Supabase.');const coach=me()?.authId||me()?.id||null;const now=new Date().toISOString();let present=0;for(const p of st()?.players||[]){const checkbox=document.getElementById(`verify-p-${p.id}`);if(!checkbox)continue;const pid=await ensurePlayerUuid(p);if(!pid)continue;const status=checkbox.checked?'present':'unjustified';if(checkbox.checked)present++;const {error}=await db.from('attendance').upsert({event_id:evId,player_id:pid,official_status:status,validated_by:UUID.test(String(coach||''))?coach:null,validated_at:now},{onConflict:'event_id,player_id'});if(error)throw error}document.getElementById('modal-verify-attendance')?.classList.remove('active');await window.loadAttendanceFromSupabase?.({silent:true,force:true});showToast(`Lista validada: ${present} asistencias oficiales computadas.`);try{renderTraining();renderHomePortalRSVP();renderHomeDashboard();renderCoachAttendanceList()}catch(_){}}catch(err){console.error('[Hotfix roll call]',err);showToast(err.message||'No se pudo guardar la lista.','error')}finally{if(btn){btn.disabled=false;btn.textContent='💾 Guardar y Validar Asistencia Oficial'}rollCallSaving=false}}
document.addEventListener('submit',saveRollCallCapture,true);

async function hydrateRpe(){const db=c(),state=st();if(!db||!state||rpeHydrating)return;rpeHydrating=true;try{await syncPlayerMappings();const {data,error}=await db.from('rpe_entries').select('id,event_id,player_id,coach_profile_id,score,source,created_at');if(error)return;state.trainingRPEs=[];for(const row of data||[]){const ev=localEventByAny(row.event_id);if(!ev)continue;if(row.source==='coach'&&!row.player_id){ev.coachRpe=Number(row.score);continue}const p=localPlayerByAny(row.player_id);if(!p)continue;state.trainingRPEs.push({eventId:ev.id,playerId:p.id,rpeVal:Number(row.score),date:ev.date||row.created_at?.slice(0,10),addedByCoach:row.source==='coach_for_player',supabaseId:row.id})}try{saveAppData(state)}catch(_){}}finally{rpeHydrating=false}}
function postProcessTrainingRpe(){if(!(typeof isCoachUser==='function'&&isCoachUser()))return;for(const ev of st()?.events||[]){if(ev.type!=='Entrenamiento'||!Number.isFinite(Number(ev.coachRpe)))continue;const card=[...document.querySelectorAll('.training-session-card')].find(x=>x.querySelector(`[onclick*="${ev.id}"]`));if(!card)continue;const panel=card.querySelector('.training-rpe-panel');if(!panel)continue;panel.classList.add('is-answered');const slider=panel.querySelector('.training-rpe-slider-wrap');if(slider)slider.outerHTML=`<div class="training-rpe-answered"><span>✓ RPE ya contestada · ${Number(ev.coachRpe)}/10</span></div>`;}}
function patchTrainingRender(){const base=window.renderTraining;if(typeof base==='function'&&!base.__hotfixC){const w=function(){const r=base.apply(this,arguments);postProcessTrainingRpe();return r};w.__hotfixC=true;window.renderTraining=w}}

function ensureDurationField(){const form=document.getElementById('form-event');if(!form||document.getElementById('event-duration-input'))return;const time=document.getElementById('event-time-input')?.closest('.form-group');if(!time)return;const g=document.createElement('div');g.className='form-group event-duration-group';g.innerHTML=`<label for="event-duration-input">Duración del entrenamiento</label><select id="event-duration-input" class="form-control"><option value="60">1 h (60 min)</option><option value="90">1 h 30 min (90 min)</option><option value="120" selected>2 h (120 min)</option></select>`;time.parentElement?.appendChild(g)}
async function persistDurationSnapshot(snapshot){if(!snapshot||snapshot.type!=='Entrenamiento')return;const db=c();if(!db)return;await new Promise(r=>setTimeout(r,700));let ev= snapshot.editingId?localEventByAny(snapshot.editingId):null;if(!ev){ev=(st()?.events||[]).filter(x=>x.type==='Entrenamiento'&&x.date===snapshot.date&&String(x.time||'').startsWith(snapshot.time)).sort((a,b)=>String(b.id).localeCompare(String(a.id)))[0]}if(!ev)return;ev.duration=snapshot.duration;const eid=await eventUuid(ev.id);if(!eid)return;const {data}=await db.from('events').select('payload,starts_at').eq('id',eid).single();if(!data)return;const end=new Date(new Date(data.starts_at).getTime()+snapshot.duration*60000).toISOString();await db.from('events').update({ends_at:end,payload:{...(data.payload||{}),duration:snapshot.duration}}).eq('id',eid);}
document.addEventListener('submit',e=>{if(e.target?.id!=='form-event')return;ensureDurationField();const type=document.getElementById('event-type-input')?.value;const duration=Number(document.getElementById('event-duration-input')?.value||120);let editingId=null;try{editingId=typeof currentEditingEventId!=='undefined'?currentEditingEventId:null}catch(_){}const snap={type,duration,editingId,date:document.getElementById('event-date-input')?.value,time:document.getElementById('event-time-input')?.value};void persistDurationSnapshot(snap)},true);
function patchEventLoading(){const base=window.loadEventsFromSupabase;if(typeof base==='function'&&!base.__hotfixC){const w=async function(){const r=await base.apply(this,arguments);for(const ev of st()?.events||[]){const d=Number(ev.rawPayload?.duration);if(Number.isFinite(d)&&d>0)ev.duration=d;else if(ev.rawPayload?.ends_at&&ev.rawPayload?.starts_at){} }return r};w.__hotfixC=true;window.loadEventsFromSupabase=w}}

function moveDeleteIntoEdit(){const base=window.editEventFromModal;if(typeof base!=='function'||base.__hotfixC)return;const w=function(eventId){const r=base.apply(this,arguments);setTimeout(()=>{const ev=localEventByAny(eventId);if(ev?.type!=='Entrenamiento')return;const actions=document.querySelector('#form-event .event-form-actions');if(!actions||actions.querySelector('.event-delete-training-btn'))return;const b=document.createElement('button');b.type='button';b.className='btn btn-outline event-delete-training-btn';b.innerHTML='<i data-lucide="trash-2"></i> Eliminar entrenamiento';b.onclick=async()=>{if(!confirm('¿Eliminar este entrenamiento? Esta acción no se puede deshacer.'))return;try{await window.deleteTrainingSessionCorrected?.(eventId);document.getElementById('modal-add-event')?.classList.remove('active')}catch(err){showToast('No se pudo eliminar el entrenamiento.','error')}};actions.prepend(b);if(window.lucide)lucide.createIcons()},0);return r};w.__hotfixC=true;window.editEventFromModal=w}

async function hydratePlan(forcedRender){const db=c(),state=st();if(!db||!state||planHydrating)return;let matchId=null;try{matchId=activeScoutingMatchId}catch(_){}if(!matchId)return;const evId=await eventUuid(matchId);if(!evId)return;planHydrating=true;try{const {data:plan,error}=await db.from('game_plans').select('id,event_id,version,status,payload,published_at').eq('event_id',evId).eq('status','published').order('version',{ascending:false}).order('published_at',{ascending:false}).limit(1).maybeSingle();if(error||!plan?.payload?.plan)return;state.matchScouting=state.matchScouting||{};const rec=state.matchScouting[matchId]||{};Object.assign(rec,{status:'published',publishedPlan:plan.payload.plan,publishedAt:plan.published_at,publicationVersion:plan.payload.publicationVersion||plan.published_at,readReceipts:rec.readReceipts||{}});state.matchScouting[matchId]=rec;await syncPlayerMappings();if(typeof isCoachUser==='function'&&isCoachUser()){const {data:reads}=await db.from('game_plan_reads').select('player_id,read_at,publication_version').eq('event_id',evId);for(const rr of reads||[]){const p=localPlayerByAny(rr.player_id);if(p)rec.readReceipts[p.id]={version:rr.publication_version||rec.publicationVersion,viewedAt:rr.read_at};}}else{const u=me();const pid=await playerUuid(u?.playerId);if(pid){const version=String(rec.publicationVersion||'');const {data:existing}=await db.from('game_plan_reads').select('id').eq('event_id',evId).eq('player_id',pid).eq('publication_version',version).maybeSingle();if(!existing){const {error:ie}=await db.from('game_plan_reads').insert({event_id:evId,game_plan_id:plan.id,player_id:pid,publication_version:version,read_at:new Date().toISOString()});if(ie)console.warn('[Hotfix plan read]',ie)}}}try{saveAppData(state)}catch(_){}if(forcedRender)forcedRender();}finally{planHydrating=false}}
function patchTactics(){const base=window.renderTactics;if(typeof base!=='function'||base.__hotfixC)return;const w=function(){const r=base.apply(this,arguments);void hydratePlan(()=>base());return r};w.__hotfixC=true;window.renderTactics=w}

function install(){if(window.__hotfix20260809c)return;if(typeof window.renderTraining!=='function'||!window.VolleySupabase){setTimeout(install,120);return}window.__hotfix20260809c=true;injectCss();ensureDurationField();patchAttendance();patchTrainingRender();patchEventLoading();moveDeleteIntoEdit();patchTactics();void syncPlayerMappings().then(async()=>{await hydrateOwnAttendance();await hydrateRpe();try{renderTraining();renderHomeDashboard();renderHomePortalRSVP()}catch(_){}});const mo=new MutationObserver(()=>{ensureDurationField();postProcessTrainingRpe()});mo.observe(document.body,{childList:true,subtree:true});console.info('[Hotfix 20260809c] activo');}
install();
})();